// FUNCTION: BFME2 0x00486C00 size=118 name=?onDie@UpgradeDie@@UAEXPBVDamageInfo@@@Z evidence=N:ledger
void UpgradeDie::onDie(const DamageInfo *damageInfo)
{
	// DieModuleInterface slot 0: `this` is the +0x10 interface sub-object, as in retail
	if (!isDieApplicable(damageInfo))
		return;
	const UpgradeTemplate *upgrade = TheUpgradeCenter->findUpgrade(((const UpgradeDieModuleData *)getModuleData())->m_upgradeToRemove);
	if (upgrade == NULL)
		return;
	if (upgrade->getUpgradeType() == UPGRADE_TYPE_PLAYER)
	{
		getObject()->getControllingPlayer()->removeUpgrade(upgrade, 0);
	}
	else
	{
		Object *producer = TheGameLogic->findObjectByID(getObject()->getProducerID());
		if (producer && producer->hasUpgrade(upgrade))
			producer->removeUpgrade(upgrade);
	}
}

